import React, { useState, useEffect } from "react";

function MERNApp() {
  const [users, setUsers] = useState([]);
  const [formData, setFormData] = useState({ name: "", email: "", role: "" });
  const [editingUser, setEditingUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const API_URL = "http://localhost:5000/api/users";

  const fetchUsers = async () => {
    try {
      console.log("Fetching users from:", API_URL);
      const response = await fetch(API_URL);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      console.log("Fetched users:", data);
      setUsers(data);
      setError("");
    } catch (err) {
      console.error("Fetch error:", err);
      setError(
        "Unable to connect to server. Make sure backend is running on port 5000."
      );
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    if (!formData.name || !formData.email || !formData.role) {
      alert("Please fill all fields");
      return;
    }

    try {
      setLoading(true);
      setError("");
      setSuccess("");

      if (editingUser) {
        console.log("Updating user:", editingUser._id);
        const response = await fetch(`${API_URL}/${editingUser._id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || "Failed to update user");
        }

        setSuccess("User updated successfully!");
        setEditingUser(null);
      } else {
        console.log("Adding new user:", formData);
        const response = await fetch(API_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.message || "Failed to add user");
        }

        const result = await response.json();
        console.log("User added:", result);
        setSuccess("User added successfully!");
      }

      setFormData({ name: "", email: "", role: "" });

      setTimeout(() => {
        fetchUsers();
      }, 500);
    } catch (err) {
      console.error("Submit error:", err);
      setError(err.message);
    } finally {
      setLoading(false);
      setTimeout(() => setSuccess(""), 3000);
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({ name: user.name, email: user.email, role: user.role });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;

    try {
      setLoading(true);
      setError("");

      console.log("Deleting user:", id);
      const response = await fetch(`${API_URL}/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || "Failed to delete user");
      }

      console.log("User deleted successfully");
      setSuccess("User deleted successfully!");

      setUsers(users.filter((u) => u._id !== id));
    } catch (err) {
      console.error("Delete error:", err);
      setError(err.message);
      fetchUsers();
    } finally {
      setLoading(false);
      setTimeout(() => setSuccess(""), 3000);
    }
  };

  const handleCancel = () => {
    setEditingUser(null);
    setFormData({ name: "", email: "", role: "" });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 py-12 px-4">
      <div className="max-w-5xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-400 mb-3">
            MERN User Manager
          </h1>
          <p className="text-slate-400 text-lg">Manage your team with style</p>
        </div>

        {error && (
          <div className="bg-red-900/30 border-l-4 border-red-500 text-red-200 px-6 py-4 rounded-r-lg mb-6 backdrop-blur-sm shadow-lg">
            <div className="flex items-center">
              <span className="text-2xl mr-3">⚠️</span>
              <span>{error}</span>
            </div>
          </div>
        )}

        {success && (
          <div className="bg-green-900/30 border-l-4 border-green-500 text-green-200 px-6 py-4 rounded-r-lg mb-6 backdrop-blur-sm shadow-lg">
            <div className="flex items-center">
              <span className="text-2xl mr-3">✓</span>
              <span>{success}</span>
            </div>
          </div>
        )}

        <div className="bg-slate-800/50 backdrop-blur-xl rounded-2xl shadow-2xl p-8 mb-10 border border-slate-700/50">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-10 h-10 bg-gradient-to-br from-cyan-500 to-purple-500 rounded-lg flex items-center justify-center">
              <span className="text-white text-xl">
                {editingUser ? "✏️" : "➕"}
              </span>
            </div>
            <h2 className="text-2xl font-bold text-white">
              {editingUser ? "Edit User" : "Add New User"}
            </h2>
          </div>

          <div className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Full Name
              </label>
              <input
                type="text"
                name="name"
                placeholder="John Doe"
                value={formData.name}
                onChange={handleChange}
                className="w-full px-4 py-3 bg-slate-700/50 border border-slate-600 rounded-xl text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-cyan-500 focus:border-transparent transition-all"
                disabled={loading}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Email Address
              </label>
              <input
                type="email"
                name="email"
                placeholder="john@example.com"
                value={formData.email}
                onChange={handleChange}
                className="w-full px-4 py-3 bg-slate-700/50 border border-slate-600 rounded-xl text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-cyan-500 focus:border-transparent transition-all"
                disabled={loading}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Role
              </label>
              <input
                type="text"
                name="role"
                placeholder="Administrator, Developer, etc."
                value={formData.role}
                onChange={handleChange}
                className="w-full px-4 py-3 bg-slate-700/50 border border-slate-600 rounded-xl text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-cyan-500 focus:border-transparent transition-all"
                disabled={loading}
              />
            </div>

            <div className="flex gap-3 pt-2">
              <button
                onClick={handleSubmit}
                disabled={loading}
                className="flex-1 bg-gradient-to-r from-cyan-500 to-purple-500 text-white px-6 py-3 rounded-xl hover:from-cyan-600 hover:to-purple-600 disabled:from-slate-600 disabled:to-slate-600 transition-all font-semibold shadow-lg hover:shadow-cyan-500/50 transform hover:scale-105"
              >
                {loading
                  ? "⏳ Processing..."
                  : editingUser
                  ? "💾 Update User"
                  : "➕ Add User"}
              </button>

              {editingUser && (
                <button
                  onClick={handleCancel}
                  disabled={loading}
                  className="px-6 py-3 bg-slate-700 text-slate-200 rounded-xl hover:bg-slate-600 transition-all font-semibold border border-slate-600"
                >
                  ✕ Cancel
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="bg-slate-800/50 backdrop-blur-xl rounded-2xl shadow-2xl p-8 border border-slate-700/50">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
                <span className="text-white text-xl">👥</span>
              </div>
              <h2 className="text-2xl font-bold text-white">Team Members</h2>
            </div>
            <div className="bg-gradient-to-r from-cyan-500/20 to-purple-500/20 border border-cyan-500/30 px-4 py-2 rounded-full">
              <span className="text-cyan-300 font-bold text-sm">
                {users.length} {users.length === 1 ? "Member" : "Members"}
              </span>
            </div>
          </div>

          {users.length === 0 ? (
            <div className="text-center py-16">
              <div className="text-6xl mb-4">📭</div>
              <p className="text-slate-400 text-xl mb-2">No team members yet</p>
              <p className="text-slate-500">
                Add your first member to get started
              </p>
            </div>
          ) : (
            <div className="grid gap-4">
              {users.map((user, index) => (
                <div
                  key={user._id}
                  className="bg-slate-700/30 border border-slate-600/50 rounded-xl p-5 hover:bg-slate-700/50 hover:border-cyan-500/50 transition-all group"
                  style={{ animationDelay: `${index * 0.05}s` }}
                >
                  <div className="flex justify-between items-start gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-3 mb-2">
                        <div className="w-12 h-12 bg-gradient-to-br from-cyan-400 to-purple-400 rounded-full flex items-center justify-center text-white font-bold text-lg flex-shrink-0">
                          {user.name.charAt(0).toUpperCase()}
                        </div>
                        <div className="min-w-0 flex-1">
                          <h3 className="text-lg font-bold text-white truncate group-hover:text-cyan-300 transition-colors">
                            {user.name}
                          </h3>
                          <p className="text-slate-400 text-sm truncate">
                            {user.email}
                          </p>
                        </div>
                      </div>
                      <div className="ml-15">
                        <span className="inline-block bg-gradient-to-r from-purple-500/20 to-pink-500/20 border border-purple-500/30 text-purple-300 px-3 py-1 rounded-full text-xs font-semibold">
                          {user.role}
                        </span>
                      </div>
                    </div>

                    <div className="flex gap-2 flex-shrink-0">
                      <button
                        onClick={() => handleEdit(user)}
                        disabled={loading}
                        className="px-4 py-2 bg-gradient-to-r from-green-600 to-emerald-600 text-white rounded-lg hover:from-green-500 hover:to-emerald-500 disabled:from-slate-600 disabled:to-slate-600 transition-all text-sm font-medium shadow-lg hover:shadow-green-500/50 transform hover:scale-105"
                      >
                        ✏️ Edit
                      </button>
                      <button
                        onClick={() => handleDelete(user._id)}
                        disabled={loading}
                        className="px-4 py-2 bg-gradient-to-r from-red-600 to-rose-600 text-white rounded-lg hover:from-red-500 hover:to-rose-500 disabled:from-slate-600 disabled:to-slate-600 transition-all text-sm font-medium shadow-lg hover:shadow-red-500/50 transform hover:scale-105"
                      >
                        🗑️ Delete
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="mt-8 text-center">
          <p className="text-slate-500 text-sm">
            Built with MongoDB • Express • React • Node.js
          </p>
        </div>
      </div>
    </div>
  );
}

export default MERNApp;
